-- 021_history_sessions_corpus.sql
-- =============================================================================
-- The historical session corpus: 38 projects (one per agent home path) + the
-- 183 sessions that ran in them, with a message count per session.
--
-- WHY: 张先生 wants his own agent history inside SeatLoom, organised by project,
-- where a project is the home path an agent harness was started from. The corpus
-- is already extracted and line-anchored in resume-contexts/ on track; this
-- migration LOADS it, it does not re-extract it.
--
-- Authority: docs/coordination/tasks/lyra/LYRA-2026-10-14-history-sessions-in-ui-contract-v1.md
-- (Lyra, packet/lyra/milestone-summary) §8.2 "Slice 1 (Onyx) — the data",
-- dispatched as disp-history-sessions-data. Acceptance: the operator's card is
-- that contract's §6.
--
-- =============================================================================
-- MEASURED SOURCES (three, cross-checked row by row; none taken on trust)
-- =============================================================================
--   A  resume-contexts/SESSIONS-FLAT.csv          183 data rows — identity, home
--                                                     path, first_ts/last_ts
--   B  resume-contexts/by-session/*.md            183 files — the 消息数 header
--                                                     line per session
--   C  AgentHistory/_manifest.json                271 entries — the archive
--                                                     index 011 describes
--                                                     (raw/src/bytes/lines/sha256)
-- Cross-checks that PASSED for all 183 rows: B's home path == A's home; B's
-- 来源文件 == A's file; C's cwd == A's home; C's raw == A's file relativised
-- under AgentHistory/; C's bytes/lines/sha256 re-computed from the file on disk
-- (169 file-backed rows agree exactly). The sum of B's 消息数 is 36680.
--
-- =============================================================================
-- WHAT THE LIVE DATABASE ALREADY HELD — read this before applying
-- =============================================================================
-- The contract (Lyra §1.1) states "archived_sessions currently holds zero rows".
-- That is true of a database built by scripts/apply-db.sh and FALSE of the live
-- one: an out-of-band load on 2026-10-08 08:15:27 UTC put the 271 manifest
-- entries into the live table (all 271 rows share that single archived_at), and
-- ROADMAP.md records it as intended state ("Archive: AgentHistory 271 sessions /
-- 14GB ingested as archived_sessions"). Measured on live, by (harness, raw_path):
--
--   * all 183 corpus sessions are ALREADY PRESENT (182 distinct live rows — the
--     one cursor directory that holds two sessions is one live row);
--   * session_date, bytes, lines, sha256 and src_path are IDENTICAL for all 183;
--   * 31 rows carry a COARSER project slug than the home path (the manifest's
--     18-project grouping: 'OfficeBench' for a session whose home is
--     .../OfficeBench/tasks, 'private_knowledge_base' for one whose home is
--     .../private_knowledge_base/step-product/mind/code/brainpp-main, ...);
--   * 165 rows carry an id that is the raw FILE name, not the session id
--     (codex 'rollout-<ts>-<uuid>', cursor '<workspace hash>', stepcode '<uuid>'
--     where the corpus's native id is the wrapped 'claude:<uuid>').
--
-- So this migration does NOT insert 183 rows next to 271 — that would put the
-- same session in the table twice and every project-grouped count would double
-- (live already holds 66 'OfficeBench' rows; 66 + 49 = 115 against the card's
-- 49). Instead it NORMALISES the 182 rows that exist and INSERTS the one that
-- does not:
--
--   §3  UPDATE ... FROM (VALUES ...) — 182 rows: id -> the native session id,
--       project -> the stripped home path, + message_count / first_ts / last_ts.
--   §4  INSERT ... ON CONFLICT DO NOTHING — 183 rows: fills what §3 did not
--       find (all 183 on a fresh database, exactly 1 on live: the second of the
--       two sessions that share one cursor directory).
--
-- The id change is the one judgement call here, and it is recorded rather than
-- assumed: 011 calls the column "native session id (per harness)"; the corpus
-- identifies sessions by that id everywhere (SESSIONS-FLAT.csv's session_key and
-- every by-session/*.md filename); and the memory layer already writes
-- source_ref as '<harness>:<native id>' (6 codex references, 3 of which resolve
-- against NO row today because the live ids are file names). No FK references
-- archived_sessions (checked: pg_constraint, pg_views, pg_trigger), so the
-- re-key is referentially safe, and the previous id is recoverable from
-- raw_path by construction (it IS the raw file name). Escalated to Aegis in the
-- delivery note with the zero-re-key alternative spelled out.
--
-- =============================================================================
-- HARD REQUIREMENTS from the dispatch, and where each is met
-- =============================================================================
--   ZERO row inserts into `sessions`, ZERO new rows into `seats`  -> this file
--     touches neither table. Verified in the delivery's reconciliation.
--   38 `projects` rows, display name = stripped path, full path retained
--     -> §2. id = name = the path with /Users/jyxc-dz-0100609/Documents/GitHub/
--     stripped (unique: the basename collides — private_knowledge_base is the
--     basename of 4 distinct homes, OfficeBench of 2), home_path = the absolute
--     path. The bare repository root strips to the empty string and is the
--     '(root)' case: its row exists so the 38 homes are all represented, its 8
--     sessions are NOT given a parent by guesswork, and
--     v_archived_sessions_normalized's R5 still reports them 'unmapped' (the
--     R4/R5 CASE branch precedes R1), which is the escalation 015 asked for.
--   183 `archived_sessions` rows, harness from the closed set, cwd = absolute
--     home path, project = stripped-path slug, raw_path/src_path/sha256 per 011
--     -> §3 + §4.
--   A message count per session from by-session/*.md, sum 36680
--     -> message_count, sourced from the 消息数 header line.
--   Idempotent: a second apply writes zero rows  -> every statement is guarded
--     (§2 ON CONFLICT, §2b WHERE ... IS DISTINCT FROM, §3 a value guard, §4 ON
--     CONFLICT). Proved in the delivery: second apply = 0 rows.
--   Reconciliation query proving the loaded counts equal the CSV's  -> §5.
--
-- =============================================================================
-- TWO MEASURED CORRECTIONS, both recorded rather than silently applied
-- =============================================================================
-- 1. SESSIONS-FLAT.csv row 19 (home .../sf-code/brainpp, codex) carries
--    session_key 019cd09f-d215-7142-a186-378692638b1e — a copy of row 18's key.
--    Its file, the manifest and by-session/*.md all name a different session,
--    019cdb69-40b9-7873-8f21-d679c6a8a1ea. Loading the CSV's key verbatim would
--    violate PRIMARY KEY (harness, id) and the migration would fail. The native
--    id is taken from the raw file name (three independent sources agree); the
--    flat CSV itself is a defect for Lyra/Aegis to fix at the source.
-- 2. cursor's chat_dump.json provably carries NO timestamps (measured: its only
--    keys are prompts/commandType). The manifest's per-directory date therefore
--    has no reproducible provenance in the indexed artifact, so session_date is
--    set to NULL for the 14 cursor rows alongside first_ts/last_ts — the UI
--    shows 时间未记录 and no date is invented. The dropped manifest dates are
--    listed in the delivery note so nothing is lost.
--
-- NOT DONE, by instruction: re-running the extraction, storing transcript
-- bodies, nesting the 38 projects into a tree (parent_project_id stays NULL —
-- the home paths are not a clean tree, the bare repository root is a path
-- ancestor of 37 others), touching the UI.
--
-- Slot 021: next after 020. POST-SEED by apply-db.sh's rule — it adds columns no
-- seed writes and inserts into two tables the seed never writes (archived_sessions
-- is written by nobody in the seed; projects is written by seed 001, which is why
-- §2 uses ON CONFLICT rather than assuming the row is absent). Additive and
-- guarded throughout: a SECOND apply performs no catalog write and no row write.
-- =============================================================================

BEGIN;

-- =============================================================================
-- 1. COLUMNS — additive, guarded, commented (015/018 house style)
-- =============================================================================
-- projects.home_path: the absolute home path an agent harness was started from.
-- The corpus's project identity IS a path; the stripped path is the display name
-- and the absolute path is kept on the row so nothing is lost. NULL = a project
-- that did not come from this corpus (the seeded 'seatloom' row is backfilled in
-- §2b because its home path is known, not guessed).
ALTER TABLE projects ADD COLUMN IF NOT EXISTS home_path TEXT NULL;

COMMENT ON COLUMN projects.home_path IS
  'Absolute home path an agent harness was started from (021, the historical-session corpus). A project in this corpus IS a home path: id/name are that path with /Users/jyxc-dz-0100609/Documents/GitHub/ stripped (the basename collides — private_knowledge_base is the basename of 4 distinct homes, OfficeBench of 2), and this column keeps the full path so nothing is lost. NULL = a project that did not come from this corpus. parent_project_id stays NULL for all 38: the home paths are not a clean tree (the bare repository root is a path ancestor of 37 others), so any nesting rule would be a guess.';

-- archived_sessions.message_count: messages in the session, from
-- resume-contexts/by-session/*.md's 消息数 header. NULL = the session has no
-- extracted conversation (the 89 manifest rows outside this corpus), which is
-- also what separates the corpus from the archive inventory in a query.
ALTER TABLE archived_sessions ADD COLUMN IF NOT EXISTS message_count INTEGER NULL;

COMMENT ON COLUMN archived_sessions.message_count IS
  'Messages in this session, counted from resume-contexts/by-session/<session>.md 消息数 header (021). Sum over the corpus is 36680. NULL = no extracted conversation exists for this row — that is what distinguishes the 183-row corpus from the 271-row archive inventory, so a project-grouped read must filter on this column being NOT NULL to avoid double counting the 89 inventory-only rows. Never a transcript body: 011 forbids storing bodies and this is a count only.';

-- first_ts / last_ts: the session's UTC instants from SESSIONS-FLAT.csv. Both
-- NULL for every cursor row — cursor's chat_dump.json carries no timestamps, and
-- no date is invented. The read path's date range comes from these two columns,
-- NOT from session_date (which the manifest load left populated for cursor with
-- a directory-level date of unreproducible provenance).
ALTER TABLE archived_sessions ADD COLUMN IF NOT EXISTS first_ts TIMESTAMPTZ NULL;
ALTER TABLE archived_sessions ADD COLUMN IF NOT EXISTS last_ts  TIMESTAMPTZ NULL;

COMMENT ON COLUMN archived_sessions.first_ts IS
  'First message instant, UTC, from resume-contexts/SESSIONS-FLAT.csv (021). NULL for all 14 cursor sessions: cursor chat_dump.json carries no timestamps (measured — its only keys are prompts/commandType), so the UI shows 时间未记录 rather than an invented date.';
COMMENT ON COLUMN archived_sessions.last_ts IS
  'Last message instant, UTC, from resume-contexts/SESSIONS-FLAT.csv (021). NULL for all 14 cursor sessions (same reason as first_ts). session_date is NOT the display source for a date range: the 2026-10-08 manifest load left it populated for cursor rows from a directory-level record, and 021 sets it to NULL there.';

-- =============================================================================
-- 2. THE 38 PROJECTS — one per home path
