-- 2b. The seeded 'seatloom' project row (seed 001: name 'SeatLoom', created
-- 2026-04-27) is one of the 38 homes and is NOT recreated or renamed — only its
-- new home_path column is filled, guarded so a second apply writes nothing. Its
-- name is deliberately left as the seed wrote it.
UPDATE projects
   SET home_path = '/Users/jyxc-dz-0100609/Documents/GitHub/seatloom'
 WHERE id = 'seatloom'
   AND home_path IS DISTINCT FROM '/Users/jyxc-dz-0100609/Documents/GitHub/seatloom';

-- =============================================================================
-- 3. NORMALISE THE 182 CORPUS ROWS THE LIVE TABLE ALREADY HAS
-- =============================================================================
-- One statement, one VALUES row per corpus session. The match key is
-- (harness, raw_path) — stable across the re-key — plus id IN (previous id,
-- native id) so the statement finds the row on the first apply (by its previous
-- id) and is a no-op on the second (by its new id). The trailing guard compares
-- every column being written, so a second apply updates ZERO rows even when the
-- row is found.
--
-- v columns: harness, raw_path, prev_id, native_id, project, cwd, session_date,
--            bytes, lines, sha256, message_count, first_ts, last_ts
UPDATE archived_sessions AS a SET
    id            = v.native_id,
    project       = v.project,
    cwd           = v.cwd,
    session_date  = v.session_date,
    bytes         = v.bytes,
    lines         = v.lines,
    sha256        = v.sha256,
    message_count = v.message_count,
    first_ts      = v.first_ts,
    last_ts       = v.last_ts
  FROM (VALUES
