  ('codex', 'raw/codex/rollout-2026-03-17T13-26-29-019cfa42-871f-7463-9184-487e93f6ada0.jsonl', 'rollout-2026-03-17T13-26-29-019cfa42-871f-7463-9184-487e93f6ada0', '019cfa42-871f-7463-9184-487e93f6ada0', 'sf-code/brainpp', '/Users/jyxc-dz-0100609/Documents/GitHub/sf-code/brainpp', '2026-03-17 15:09', 1604279::bigint, 1249::int, '274f27c890ff0481629a49e446e9e9739858a0bc38c0519cfa99346b8da54a0d', 93::int, '2026-03-17T05:26:32.061Z'::timestamptz, '2026-03-17T07:09:59.565Z'::timestamptz),
  ('codex', 'raw/codex/rollout-2026-05-21T14-59-45-019e4955-42d5-7f30-9637-552b84c65d97.jsonl', 'rollout-2026-05-21T14-59-45-019e4955-42d5-7f30-9637-552b84c65d97', '019e4955-42d5-7f30-9637-552b84c65d97', 'ai-assistant/sf-package/storage', '/Users/jyxc-dz-0100609/Documents/GitHub/ai-assistant/sf-package/storage', '2026-05-27 13:23', 10629874::bigint, 6022::int, '7515a647556190584ccc5900a45c8fc395506215011522623d12f74df6ee37d7', 625::int, '2026-05-21T06:59:48.582Z'::timestamptz, '2026-05-27T05:23:53.503Z'::timestamptz),
  ('codex', 'raw/codex/rollout-2026-04-09T20-37-02-019d723e-f8d5-7123-9cb7-f16dac8e51f6.jsonl', 'rollout-2026-04-09T20-37-02-019d723e-f8d5-7123-9cb7-f16dac8e51f6', '019d723e-f8d5-7123-9cb7-f16dac8e51f6', 'sf-code/brainpp', '/Users/jyxc-dz-0100609/Documents/GitHub/sf-code/brainpp', '2026-04-09 21:04', 290158::bigint, 167::int, '89940b93b1c0aa1c9d9e13e54edca1d8eecc2f40e845375877a335c22e2c3f95', 7::int, '2026-04-09T12:38:02.874Z'::timestamptz, '2026-04-09T13:04:08.100Z'::timestamptz),
